          {value}
        </span>
        <span className="text-sm text-secondary-600 dark:text-secondary-400">
          {unit}
        </span>
      </div>
      {description && (
        <p className="text-xs text-secondary-600 dark:text-secondary-400 mt-1">
          {description}
        </p>
      )}
    </div>
