        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          plan: signupData.accountType,
          email: signupData.email,
          password: signupData.password,
          company_code: signupData.accountType === 'company' ? signupData.companyName : undefined,
