// =============================================================================
// SECURE EMAIL MVP - TYPE DEFINITIONS
// =============================================================================

// User-related types
export interface User {
  id: string;
  email: string;
  created_at: string;
  updated_at: string;
}

// Authentication types
export interface LoginCredentials {
  email: string;
  password: string;
  totpCode: string;
}

export interface SignupData {
  email: string;
  password: string;
  confirm_password: string;
}

export interface AuthTokens {
  accessToken: string;
  refreshToken: string;
}

export interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
}

// Theme types
export type Theme = 'light' | 'dark' | 'system';

// Email types
export interface Email {
  id: string;
  from?: string;
  to?: string;
  subject: string;
  content: string;
  date?: string;
  read?: boolean;
  important?: boolean;
  attachments?: EmailAttachment[];
  // Additional properties used by components
  sender?: string;
  recipients?: string[];
  isRead?: boolean;
  isStarred?: boolean;
  isEncrypted?: boolean;
  hasAttachments?: boolean;
  receivedAt?: string;
  createdAt?: string;
  labels?: string[];
}

export interface EmailAttachment {
  id?: string;
  name: string;
  size: string | number;
  type?: string;
  isEncrypted?: boolean;
}

// API response types
export interface ApiResponse<T = unknown> {
  success: boolean;
  data?: T;
  error?: string;
  message?: string;
}

// Navigation types
export interface NavigationItem {
  name: string;
